use crate::repo::OrderRepo;

#[derive(Debug, PartialEq, Eq)]
pub enum CancelResult {
    Cancelled { refund_cents: i64 },
    AlreadyCancelled,
    Expired,
    NotFound,
}

pub fn cancel_order(
    repo: &mut OrderRepo,
    order_id: u64,
    now_secs: i64,
    window_secs: i64,
) -> CancelResult {
    let Some(mut row) = repo.load(order_id) else {
        return CancelResult::NotFound;
    };
    if row.status == "cancelled" {
        return CancelResult::AlreadyCancelled;
    }
    let refund_cents = if row.status == "paid" {
        let paid_at = row.paid_at.unwrap_or(0);
        if now_secs - paid_at > window_secs {
            return CancelResult::Expired;
        }
        row.total_cents
    } else {
        0
    };
    row.status = "cancelled".to_string();
    row.cancelled_at = Some(now_secs);
    repo.save(row);
    CancelResult::Cancelled { refund_cents }
}

pub fn refund_summary(repo: &OrderRepo, order_id: u64) -> Option<String> {
    let row = repo.load(order_id)?;
    if row.status == "cancelled" {
        let ts = row.cancelled_at.unwrap_or(0);
        Some(format!("cancelled at {ts}: {}", row.customer_note))
    } else {
        Some(format!("status {}: {}", row.status, row.customer_note))
    }
}

