#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OrderId(pub u64);

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OrderState {
    Draft,
    Paid { paid_at: i64, total_cents: i64 },
    Cancelled { cancelled_at: i64 },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CancelOutcome {
    Cancelled { refund_cents: i64 },
    AlreadyCancelled,
    Expired,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Order {
    id: OrderId,
    state: OrderState,
    customer_note: String,
}

impl Order {
    pub fn new(id: OrderId, state: OrderState, customer_note: String) -> Self {
        Self { id, state, customer_note }
    }

    pub fn id(&self) -> OrderId {
        self.id
    }

    pub fn state(&self) -> &OrderState {
        &self.state
    }

    pub fn customer_note(&self) -> &str {
        &self.customer_note
    }

    pub fn cancel(&mut self, now_secs: i64, window_secs: i64) -> CancelOutcome {
        match self.state {
            OrderState::Cancelled { .. } => CancelOutcome::AlreadyCancelled,
            OrderState::Draft => {
                self.state = OrderState::Cancelled { cancelled_at: now_secs };
                CancelOutcome::Cancelled { refund_cents: 0 }
            }
            OrderState::Paid { paid_at, total_cents } => {
                if now_secs - paid_at > window_secs {
                    return CancelOutcome::Expired;
                }
                self.state = OrderState::Cancelled { cancelled_at: now_secs };
                CancelOutcome::Cancelled { refund_cents: total_cents }
            }
        }
    }
}

