use crate::domain::{Order, OrderId, OrderState};

#[derive(Debug, Clone)]
struct StoredOrderRow {
    id: u64,
    status: String,
    total_cents: i64,
    paid_at: Option<i64>,
    cancelled_at: Option<i64>,
    customer_note: String,
}

pub struct OrderRepo {
    row: StoredOrderRow,
}

impl OrderRepo {
    pub fn from_domain(order: &Order) -> Self {
        Self { row: encode(order) }
    }

    pub fn load(&self, id: OrderId) -> Option<Order> {
        if self.row.id != id.0 {
            return None;
        }
        decode(&self.row)
    }

    pub fn save(&mut self, order: &Order) {
        self.row = encode(order);
    }
}

fn decode(row: &StoredOrderRow) -> Option<Order> {
    let state = match row.status.as_str() {
        "draft" => OrderState::Draft,
        "paid" => OrderState::Paid {
            paid_at: row.paid_at?,
            total_cents: row.total_cents,
        },
        "cancelled" => OrderState::Cancelled {
            cancelled_at: row.cancelled_at?,
        },
        _ => return None,
    };
    Some(Order::new(OrderId(row.id), state, row.customer_note.clone()))
}

fn encode(order: &Order) -> StoredOrderRow {
    let (status, total_cents, paid_at, cancelled_at) = match *order.state() {
        OrderState::Draft => ("draft", 0, None, None),
        OrderState::Paid { paid_at, total_cents } => ("paid", total_cents, Some(paid_at), None),
        OrderState::Cancelled { cancelled_at } => ("cancelled", 0, None, Some(cancelled_at)),
    };
    StoredOrderRow {
        id: order.id().0,
        status: status.to_string(),
        total_cents,
        paid_at,
        cancelled_at,
        customer_note: order.customer_note().to_string(),
    }
}

