use crate::domain::{CancelOutcome, OrderId};
use crate::repo::OrderRepo;

pub fn cancel_order(
    repo: &mut OrderRepo,
    id: OrderId,
    now_secs: i64,
    window_secs: i64,
) -> Option<CancelOutcome> {
    let mut order = repo.load(id)?;
    let outcome = order.cancel(now_secs, window_secs);
    if matches!(outcome, CancelOutcome::Cancelled { .. }) {
        repo.save(&order);
    }
    Some(outcome)
}

