use std::time::{SystemTime, UNIX_EPOCH};

use crate::gateway::PaymentGateway;
use crate::store::Store;

const GRACE_SECS: i64 = 7 * 86_400;
const PERIOD_SECS: i64 = 30 * 86_400;

pub fn run_renewal(
    store: &mut Store,
    gateway: &mut PaymentGateway,
    sub_id: u64,
    coupon_pct: u32,
) -> Result<Option<i64>, &'static str> {
    let sub = store.load_sub(sub_id)?;
    if sub.paused {
        return Ok(None);
    }
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    if now_secs < sub.period_end_secs {
        return Ok(None);
    }
    let overdue = now_secs - sub.period_end_secs;
    if overdue > GRACE_SECS {
        return Err("grace period exceeded");
    }
    let gross = sub.base_price_cents * i64::from(sub.seats);
    let volume_pct = if sub.seats >= 25 {
        15
    } else if sub.seats >= 10 {
        10
    } else {
        0
    };
    let loyalty_pct = if sub.loyal_months >= 24 { 10 } else if sub.loyal_months >= 12 { 5 } else { 0 };
    let total_pct = (volume_pct + loyalty_pct + coupon_pct).min(30);
    let due_cents = gross - (gross * i64::from(total_pct)) / 100;
    let next_end = now_secs + PERIOD_SECS;
    if due_cents > 0 {
        gateway.charge(sub.id, due_cents)?;
    }
    store.record_renewal(sub.id, due_cents, next_end)?;
    Ok(Some(due_cents))
}

