use crate::store::CustomerStore;

pub fn update_billing_email(
    store: &CustomerStore,
    customer_id: u64,
    new_email: &str,
) -> Result<u64, &'static str> {
    let trimmed = new_email.trim();
    if trimmed.is_empty() || !trimmed.contains('@') {
        return Err("invalid email");
    }
    let mut row = store.lock_row()?;
    if row.id != customer_id {
        return Err("customer not found");
    }
    if row.email == trimmed {
        return Ok(row.version);
    }
    row.email = trimmed.to_string();
    row.version += 1;
    Ok(row.version)
}

