use crate::domain::{Approval, OrderState, RefundReason, Role};

pub fn authorize_refund(
    role: Role,
    state: OrderState,
    reason: RefundReason,
    amount_cents: i64,
) -> Approval {
    if amount_cents > 50_000 && role != Role::Finance {
        return Approval::NeedsManager;
    }
    if role == Role::Finance {
        return Approval::Allowed;
    }
    if role == Role::Support {
        if reason == RefundReason::Damaged {
            return Approval::Allowed;
        } else if state == OrderState::Paid {
            return Approval::Allowed;
        } else if state == OrderState::Shipped {
            return Approval::NeedsManager;
        } else {
            return Approval::NeedsManager;
        }
    }
    if role == Role::Customer {
        if state == OrderState::Paid {
            if reason == RefundReason::ChangedMind {
                return Approval::Allowed;
            } else {
                return Approval::Allowed;
            }
        } else if state == OrderState::Delivered && reason == RefundReason::Damaged {
            return Approval::NeedsManager;
        }
    }
    Approval::Denied
}

