use crate::domain::{Approval, OrderState, RefundReason, Role};

const MANAGER_THRESHOLD_CENTS: i64 = 50_000;

pub fn authorize_refund(
    role: Role,
    state: OrderState,
    reason: RefundReason,
    amount_cents: i64,
) -> Approval {
    if amount_cents > MANAGER_THRESHOLD_CENTS && role != Role::Finance {
        return Approval::NeedsManager;
    }
    match (role, state, reason) {
        (Role::Finance, _, _) => Approval::Allowed,
        (Role::Support, _, RefundReason::Damaged)
        | (Role::Support, OrderState::Paid, RefundReason::ChangedMind) => Approval::Allowed,
        (Role::Support, OrderState::Shipped | OrderState::Delivered, RefundReason::ChangedMind) => {
            Approval::NeedsManager
        }
        (Role::Customer, OrderState::Paid, _) => Approval::Allowed,
        (Role::Customer, OrderState::Delivered, RefundReason::Damaged) => Approval::NeedsManager,
        (Role::Customer, OrderState::Shipped, _)
        | (Role::Customer, OrderState::Delivered, RefundReason::ChangedMind) => Approval::Denied,
    }
}

