pub fn handle_payout(account: &mut Account, amount_cents: i64, db_online: bool) -> HttpReply {
    match execute_payout(account, amount_cents, db_online) {
        Ok(_) => HttpReply { status: 200, retryable: false },
        Err(AppError::InsufficientBalance { .. }) => HttpReply { status: 422, retryable: false },
        Err(AppError::AlreadySettled) => HttpReply { status: 409, retryable: false },
