use crate::error::InfraError;

pub struct Account {
    pub balance_cents: i64,
    pub settled: bool,
}

#[derive(Debug, PartialEq, Eq)]
pub enum PayoutOutcome {
    Settled { remaining_cents: i64 },
    AlreadySettled,
    InsufficientBalance { available: i64, requested: i64 },
}

pub fn execute_payout(
    account: &mut Account,
    amount_cents: i64,
    db_online: bool,
) -> Result<PayoutOutcome, InfraError> {
    if !db_online {
        return Err(InfraError::DbUnavailable("primary offline".into()));
    }
    if account.settled {
        return Ok(PayoutOutcome::AlreadySettled);
    }
    if account.balance_cents < amount_cents {
        return Ok(PayoutOutcome::InsufficientBalance {
            available: account.balance_cents,
            requested: amount_cents,
        });
    }
    account.balance_cents -= amount_cents;
    account.settled = true;
    Ok(PayoutOutcome::Settled {
        remaining_cents: account.balance_cents,
    })
}

