use std::time::{SystemTime, UNIX_EPOCH};

pub struct RefundReceipt {
    pub amount_dollars: f64,
    pub issued_epoch: u64,
}

pub fn compute_refund(paid_dollars: f64, restock_pct: f64) -> RefundReceipt {
    let issued_epoch = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let amount_dollars = paid_dollars * (1.0 - restock_pct / 100.0);
    RefundReceipt { amount_dollars, issued_epoch }
}

