#[derive(Debug)]
pub enum PostError {
    AfterCutoff { ledger_id: u64, utc_hour: u8 },
}

// Clearinghouse settlement closes at 23:00 UTC; later postings roll to next day.
pub fn post_entry(posting: &Posting, utc_hour: u8) -> Result<(), PostError> {
    if utc_hour >= 23 {
        return Err(PostError::AfterCutoff {
            ledger_id: posting.ledger_id,
            utc_hour,
        });
    }
    let _ = (posting.debit_acct, posting.credit_acct, posting.cents);
    Ok(())
}

