#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ShipmentState {
    Pending,
    Packed,
    Dispatched { tracking: String },
    Cancelled,
}

pub struct Shipment {
    id: u64,
    state: ShipmentState,
}

impl Shipment {
    pub fn new(id: u64, state: ShipmentState) -> Self {
        Self { id, state }
    }

    pub fn id(&self) -> u64 {
        self.id
    }

    pub fn is_terminal(&self) -> bool {
        match self.state {
            ShipmentState::Pending | ShipmentState::Packed => false,
            ShipmentState::Dispatched { .. } | ShipmentState::Cancelled => true,
        }
    }

    pub fn dispatch(&mut self, tracking: String) -> Result<(), &'static str> {
        match self.state {
            ShipmentState::Packed => {
                self.state = ShipmentState::Dispatched { tracking };
                Ok(())
            }
            ShipmentState::Pending
            | ShipmentState::Dispatched { .. }
            | ShipmentState::Cancelled => Err("cannot dispatch"),
        }
    }

    pub fn cancel(&mut self) -> Result<(), &'static str> {
        match self.state {
            ShipmentState::Pending | ShipmentState::Packed => {
                self.state = ShipmentState::Cancelled;
                Ok(())
            }
            ShipmentState::Dispatched { .. } | ShipmentState::Cancelled => {
                Err("cannot cancel")
            }
        }
    }
}

